def write_notification(email: str, message: str = "some notification"):
    with open("log.txt", mode="w") as email_file:
        email_file.write(f"Notification to {email}: {message}\n")

from fastapi import BackgroundTasks, FastAPI, Depends

app = FastAPI()

def get_background_logger(background_tasks: BackgroundTasks):
    return background_tasks

@app.post("/items/")
async def create_item(email: str, background_tasks: BackgroundTasks = Depends(get_background_logger)):
    background_tasks.add_task(write_notification, email, message="Item created successfully")
    return {"message": "Item received and processing in background"}

